CREATE TABLE IF NOT EXISTS sellers (id CHAR(36) PRIMARY KEY,mobile_number VARCHAR(10) UNIQUE NOT NULL,shop_name VARCHAR(100) NOT NULL,address_line TEXT NULL,area VARCHAR(100) NULL,city VARCHAR(100) NULL,state VARCHAR(100) NULL,pincode VARCHAR(10) NULL,latitude DECIMAL(10,7) NULL,longitude DECIMAL(10,7) NULL,location_url TEXT NULL,verification_status ENUM('PENDING','VERIFIED','REJECTED') NOT NULL DEFAULT 'PENDING',password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT sellers_latitude_check CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),CONSTRAINT sellers_longitude_check CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180));
